import type { Entity, Field, Option } from './types.ts';

// ---------- field helpers ----------
const t = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'text', ...x });
const ta = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'textarea', wide: true, ...x });
const num = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'number', ...x });
const int = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'int', ...x });
const money = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'money', ...x });
const date = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'date', ...x });
const dt = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'datetime', ...x });
const bool = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'bool', ...x });
const ref = (key: string, label: string, target: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'ref', ref: target, ...x });
const user = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'user', ref: 'users', ...x });
const users = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'users', ref: 'users', ...x });
const sel = (key: string, label: string, options: Option[], x: Partial<Field> = {}): Field => ({ key, label, type: 'select', options, ...x });
const json = (key: string, label: string, x: Partial<Field> = {}): Field => ({ key, label, type: 'json', hidden: true, ...x });
const tags = (key = 'tags', label = 'Теги', x: Partial<Field> = {}): Field => ({ key, label, type: 'tags', ...x });
const o = (value: string, label: string, color?: string): Option => ({ value, label, color });
const guid = (): Field => t('onec_guid', 'GUID в 1С', { hidden: true });

