export const ENTITIES: Record<string, Entity> = Object.fromEntries(E.map((e) => [e.key, e]));
export const ENTITY_LIST = E;

export function entity(key: string): Entity {
  const e = ENTITIES[key];
  if (!e) throw Object.assign(new Error(`Неизвестный объект: ${key}`), { status: 404 });
  return e;
}

export function field(ent: Entity, key: string): Field | undefined {
  return ent.fields.find((f) => f.key === key);
}

export function optionLabel(ent: string, fieldKey: string, value: unknown): string {
  const f = ENTITIES[ent]?.fields.find((x) => x.key === fieldKey);
  return f?.options?.find((x) => x.value === String(value))?.label ?? String(value ?? '');
}

/** Which module a permission check uses for an entity */
export function moduleOf(entityKey: string): string {
  return ENTITIES[entityKey]?.module ?? 'settings';
}
